window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[210]={"id":"210","numero":210,"titre":"Pneumopathies interstitielles diffuses","objectifs":[{"id":"210-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition des pneumopathies interstitielles diffuses (PID), connaître les grandes catégories de PID","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">PID</span> correspondent à un ensemble hétérogène d'affections qui touchent l'<span class=\"kw-def\">interstitium pulmonaire</span> — aussi appelées <em>pneumopathies infiltratives diffuses</em>. Plus de <span class=\"kw-chiffre\">200 entités</span> recensées, regroupées en deux grandes catégories selon que la cause est connue ou non.</p>\n\n      <table >\n        <thead><tr><th>Catégorie</th><th>Part</th><th>Exemples principaux</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>PID secondaires</strong> (cause connue)</td>\n            <td><span class=\"kw-chiffre\">35 %</span></td>\n            <td>\n              <strong>Cardiaque :</strong> <span class=\"kw-ci\">insuffisance cardiaque</span> gauche<br>\n              <strong>Infectieuse :</strong> <span class=\"kw-etio\">tuberculose</span> ; viroses (dont <span class=\"kw-clinique\">SARS-CoV-2</span>) ; pneumocystose ; champignons<br>\n              <strong>Médicamenteuse :</strong> <span class=\"kw-ttt\">méthotrexate</span> ; <span class=\"kw-ttt\">bléomycine</span> ; <span class=\"kw-ttt\">amiodarone</span> ; <span class=\"kw-ttt\">cyclophosphamide</span><br>\n              <strong><span class=\"kw-ci\">Hypersensibilité</span> :</strong> <span class=\"kw-clinique\">PHS</span><br>\n              <strong>Connectivites :</strong> <span class=\"kw-clinique\">PR</span> ; <span class=\"kw-clinique\">sclérodermie</span> ; myosite ; Sjögren<br>\n              <strong>Pneumoconioses :</strong> asbestose ; silicose<br>\n              <strong>Malignes :</strong> lymphangite carcinomateuse ; adénocarcinome lépidique\n            </td>\n          </tr>\n          <tr>\n            <td><strong>PID de cause inconnue</strong> (idiopathiques + <span class=\"kw-clinique\">sarcoïdose</span>)</td>\n            <td><span class=\"kw-chiffre\">65 %</span></td>\n            <td>\n              <strong><span class=\"kw-clinique\">FPI</span></strong> <em>(≈<span class=\"kw-chiffre\"> 55 %</span> des idiopathiques)</em><br>\n              <strong><span class=\"kw-clinique\">PINS</span></strong> <em>(≈<span class=\"kw-chiffre\"> 25 %</span>)</em><br>\n              <strong>Pneumopathie organisée cryptogénique (POC)</strong><br>\n              <strong><span class=\"kw-clinique\">Sarcoïdose</span></strong><br>\n              <strong>Histiocytose langerhansienne</strong><br>\n              <strong>Pneumopathie à <span class=\"kw-bio\">éosinophiles</span></strong>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Points communs anatomiques et physiopathologiques</h5>\n      <ul>\n        <li><strong>Anatomie</strong> — atteinte du <span class=\"kw-def\">lobule pulmonaire</span> (unité polyédrique <span class=\"kw-chiffre\">1–2,5 cm</span> ; <span class=\"kw-chiffre\">3–5</span> acini ; <span class=\"kw-chiffre\">30–60</span> alvéoles par acinus) ; cible : <span class=\"kw-def\">interstitium pulmonaire</span> (tissu conjonctif de soutien des axes broncho-vasculaires, septas inter- et intra-lobulaires, tissu sous-pleural).</li>\n        <li><strong><span class=\"kw-bio\">Anatomopathologie</span></strong> — infiltrat cellulaire ou œdémateux → fibrose possible → <span class=\"kw-alerte\">désorganisation irréversible de l'architecture pulmonaire</span> avec altération de la ventilation et des échanges gazeux.</li>\n        <li><strong>Imagerie</strong> — opacités parenchymateuses <span class=\"kw-imagerie\">diffuses, bilatérales, non systématisées, habituellement symétriques</span> ; <span class=\"kw-imagerie\">TDM</span>-HR souvent indispensable.</li>\n        <li><strong>Clinique</strong> — symptômes non spécifiques (<span class=\"kw-clinique\">toux sèche</span>, <span class=\"kw-clinique\">dyspnée d'effort</span>), <span class=\"kw-clinique\">crépitants</span> fréquents, retentissement fonctionnel pouvant aboutir à une <span class=\"kw-alerte\">insuffisance respiratoire avec hypoxémie</span>.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 203 — <span class=\"kw-clinique\">Dyspnée</span> · 204 — Toux · 207 — Opacité intra-thoracique Adulte/Enfant</em></p>","frequence":0},{"id":"210-2","rang":"B","rubrique":"Diagnostic positif","titre":"Pneumoconiose : connaître les modalités du diagnostic le diagnostic","contenu":"<p>Le diagnostic d'une <span class=\"kw-def\">pneumoconiose</span> repose sur le triptyque <strong>curriculum laboris + aspect radiologique compatible + délai d'exposition cohérent</strong>. La <span class=\"kw-clinique\">biopsie pulmonaire n'est pas indispensable</span> au diagnostic — le LBA confirme l'exposition mais n'affirme pas la maladie.</p>\n\n      <table >\n        <thead><tr><th>Pneumoconiose</th><th>Exposition</th><th><span class=\"kw-imagerie\">TDM</span>-HR</th><th>LBA / <span class=\"kw-bio\">histologie</span></th><th><span class=\"kw-clinique\">Évolution</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Asbestose</strong> (<span class=\"kw-ttt\">amiante</span>, la plus fréquente)</td>\n            <td>Chantiers navals, ciment, automobile, matériel isolant</td>\n            <td>\n              <strong>Profil parenchymateux :</strong> <span class=\"kw-imagerie\">proche de la FPI (PIC)</span> ; bronchectasies de traction ; réticulations intra-lobulaires ; rayons de miel<br>\n              <strong>Topographie :</strong> <span class=\"kw-imagerie\">basale + périphérique</span><br>\n              <strong>Signe spécifique :</strong> <span class=\"kw-imagerie\">plaques pleurales calcifiées</span> (<span class=\"kw-chiffre\">30–80 %</span>, évocatrices) en fenêtre médiastinale\n            </td>\n            <td>\n              <strong>LBA :</strong> <span class=\"kw-bio\">alvéolite neutrophilique</span> + corps asbestosiques (ferrugineux)<br>\n              <strong><span class=\"kw-bio\">Histologie</span> :</strong> pneumopathie interstitielle commune (PIC)\n            </td>\n            <td><span class=\"kw-alerte\">Évolue toujours vers l'insuffisance respiratoire chronique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Silicose</strong></td>\n            <td>Mineurs, tailleurs de pierre, fonderies, sablage, verre/céramique, prothésistes dentaires, travailleurs textile</td>\n            <td>\n              <strong>Parenchyme :</strong> <span class=\"kw-imagerie\">micronodules à contours nets, diffus</span> ; prédominance <span class=\"kw-imagerie\">lobes supérieurs (postéro-supérieurs)</span> ; confluence possible en <span class=\"kw-imagerie\">masses pseudo-tumorales</span><br>\n              <strong>ADP :</strong> <span class=\"kw-imagerie\">médiastinales avec calcifications en « coquille d'œuf »</span>\n            </td>\n            <td>\n              <strong>LBA :</strong> <span class=\"kw-bio\">alvéolite macrophagique</span> + <span class=\"kw-bio\">corps biréfringents</span><br>\n              <strong><span class=\"kw-bio\">Histologie</span> :</strong> <span class=\"kw-bio\">nodule fibro-hyalin silicotique</span>\n            </td>\n            <td>\n              <strong>Phase de latence :</strong> longue<br>\n              <strong>Complication majeure :</strong> <span class=\"kw-alerte\">cancer bronchique primitif</span> ajouté à la liste des maladies professionnelles imputables (doit être associé à une silicose caractérisée)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Bérylliose</strong></td>\n            <td>Fabrication d'alliages, industrie nucléaire, électronique, aéronautique, céramiques, prothésistes dentaires</td>\n            <td><span class=\"kw-imagerie\">Adénopathies médiastinales + syndrome infiltrant parenchymateux</span> — tableau proche de la <span class=\"kw-clinique\">sarcoïdose</span></td>\n            <td>—</td>\n            <td>Fibrose progressive possible</td>\n          </tr>\n          <tr>\n            <td><strong>Sidérose</strong></td>\n            <td>Soudage à l'arc (fumées d'oxyde de fer)</td>\n            <td><span class=\"kw-imagerie\">Micronodules pulmonaires ± emphysème</span></td>\n            <td>—</td>\n            <td>Généralement peu évolutive</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Lien de causalité exposition ↔ PID</strong> — requiert de préciser <span class=\"kw-chiffre\">temps de latence</span>, <span class=\"kw-chiffre\">intensité</span> et <span class=\"kw-chiffre\">durée</span> d'exposition. Le LBA <em>affirme l'exposition</em> mais <em>n'affirme pas la maladie</em>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 309 — Tumeurs du poumon</em></p>","frequence":1},{"id":"210-3","rang":"B","rubrique":"Diagnostic positif","titre":"Pneumopathie d’hypersensibilité : connaître les modalités du diagnostic le diagnostic","contenu":"<p>La <span class=\"kw-def\">pneumopathie d'hypersensibilité (PHS)</span> est liée à une <strong><span class=\"kw-ci\">hypersensibilité</span> retardée</strong> à des <span class=\"kw-clinique\">antigènes organiques inhalés de façon répétée</span>. Maladie professionnelle reconnue (tableaux 47 RG, 45 RG, 45 RA, 62 RG). Le <span class=\"kw-alerte\">drapeau rouge</span> sémiologique est une <span class=\"kw-alerte\">symptomatologie rythmée par l'exposition</span>.</p>\n\n      <h5>Étiologies — répertoire des expositions</h5>\n      <table >\n        <thead><tr><th>Milieu</th><th>Maladie</th><th><span class=\"kw-bio\">Antigène</span> responsable</th></tr></thead>\n        <tbody>\n          <tr><td rowspan=\"4\"><strong>Agricole</strong></td><td>Poumon d'éleveur d'oiseaux</td><td><span class=\"kw-bio\">Protéines aviaires</span> (pigeons, tourterelles, poules)</td></tr>\n          <tr><td>Poumon de fermier</td><td><span class=\"kw-bio\">Foin moisi</span> — actinomycètes thermophiles <em>(Micropolyspora faeni)</em></td></tr>\n          <tr><td>Poumon de fabricants de fromage</td><td>Exposition <span class=\"kw-etio\">fongique</span></td></tr>\n          <tr><td>Maladie des engrais / du compost / des champignonnistes</td><td>Moisissures variées</td></tr>\n          <tr><td rowspan=\"4\"><strong>Non agricole</strong></td><td>Maladie des climatiseurs / humidificateurs</td><td>Actinomycètes, micromycètes</td></tr>\n          <tr><td>Oiseaux de compagnie</td><td>Protéines aviaires</td></tr>\n          <tr><td>Maladies des détergents / fabricants de saucisson / ouvriers papeterie</td><td>Moisissures</td></tr>\n          <tr><td>Maladies professionnelles métalliques</td><td>Zinc, cobalt, zirconium</td></tr>\n        </tbody>\n      </table>\n\n      <h5>Formes cliniques</h5>\n      <table >\n        <thead><tr><th>Forme</th><th>Présentation</th><th>Imagerie</th><th><span class=\"kw-clinique\">Évolution</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Aiguë / subaiguë</strong> <em>(non fibrosante)</em></td>\n            <td><span class=\"kw-clinique\">Syndrome pseudo-grippal fébrile</span> survenant <span class=\"kw-chiffre\">4 à 10 h après exposition</span> à l'<span class=\"kw-bio\">antigène</span></td>\n            <td>\n              <strong><span class=\"kw-imagerie\">RXT</span> :</strong> opacités infiltrantes diffuses bilatérales<br>\n              <strong><span class=\"kw-imagerie\">TDM</span> :</strong> <span class=\"kw-imagerie\">verre dépoli</span> ; <span class=\"kw-imagerie\">nodules flous peu denses centro-lobulaires</span>\n            </td>\n            <td>Spontanément favorable après éviction OU <span class=\"kw-clinique\">évolution</span> chronique sur quelques semaines/mois si exposition persistante</td>\n          </tr>\n          <tr>\n            <td><strong>Chronique</strong> <em>(fibrosante)</em></td>\n            <td><span class=\"kw-clinique\">Toux</span>, <span class=\"kw-clinique\">dyspnée d'effort</span>, <span class=\"kw-clinique\">râles crépitants</span> ± <span class=\"kw-clinique\">râles piaulants inspiratoires (squeaks)</span> — atteinte bronchiolaire</td>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> :</strong> <span class=\"kw-imagerie\">aspect de fibrose type PIC</span></td>\n            <td><span class=\"kw-alerte\">Fibrose progressive indépendante</span> de l'éviction → <span class=\"kw-alerte\">insuffisance respiratoire</span> ; aggrave nettement le <span class=\"kw-def\">pronostic</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Outils diagnostiques complémentaires</h5>\n      <ul>\n        <li><strong><span class=\"kw-bio\">Sérologie</span></strong> — <span class=\"kw-bio\">précipitines sériques (IgG)</span> spécifiques contre l'Ag suspecté. <em>N'affirme pas le diagnostic ; leur absence ne l'exclut pas</em>.</li>\n        <li><strong>LBA</strong> (surtout en phase aiguë) — <span class=\"kw-bio\">alvéolite très riche en lymphocytes (&gt; 50 %)</span> à prédominance <span class=\"kw-bio\">CD8⁺</span> (rapport <span class=\"kw-chiffre\">CD4</span>/CD8 &lt; 1).</li>\n        <li><strong>Enquête à domicile</strong> par <span class=\"kw-clinique\">les</span> conseillers médicaux d'environnement intérieur.</li>\n        <li><strong><span class=\"kw-ttt\">Biopsie</span> pulmonaire vidéo-chirurgicale</strong> exceptionnelle : granulomes mal formés, prédominance bronchocentrique des lésions.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Mnémo discriminant LBA</strong> — <span class=\"kw-clinique\">sarcoïdose</span> = <span class=\"kw-bio\">CD4⁺ ↑</span> (rapport <span class=\"kw-chiffre\">CD4</span>/CD8 &gt; 3) ; PHS = <span class=\"kw-bio\">CD8⁺ ↑</span> (rapport &lt; 1). C'est l'inverse, à ne pas confondre.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 192 — Pathologie <span class=\"kw-etio\">auto-immune</span></em></p>","frequence":1},{"id":"210-4","rang":"B","rubrique":"Étiologie","titre":"Connaître les principales causes de PID secondaires","contenu":"<p><span class=\"kw-clinique\">Les</span> PID secondaires (cause connue, <span class=\"kw-chiffre\">35 % du total</span>) se répartissent selon le mode d'installation (aigu &lt;<span class=\"kw-chiffre\"> 3 semaines</span> <span class=\"kw-bio\">vs</span> subaigu/chronique) et le mécanisme. La distinction est diagnostique <strong>et</strong> pronostique.</p>\n\n      <h5>Mode d'installation aigu (&lt;<span class=\"kw-chiffre\"> 3 semaines</span>)</h5>\n      <table >\n        <thead><tr><th>Critère</th><th><span class=\"kw-clinique\">Œdème</span> pulmonaire hémodynamique</th><th>Pneumonies infectieuses</th><th><span class=\"kw-alerte\">SDRA</span></th><th>Exacerbation de PID-SC</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Fièvre</span></strong></td><td>NON</td><td>OUI</td><td>±</td><td>±</td></tr>\n          <tr>\n            <td><strong>Mécanisme</strong></td>\n            <td><span class=\"kw-clinique\">IDM</span><br>Valvulopathie mitrale<br>Surcharge hémodynamique</td>\n            <td>\n              <strong><span class=\"kw-ttt\">PAC</span> :</strong> <span class=\"kw-etio\">pneumocoque</span> ; légionelles ; mycoplasme ; <span class=\"kw-clinique\">chlamydia</span> ; <span class=\"kw-etio\">grippe</span> ; COVID-19<br>\n              <strong><span class=\"kw-etio\">Tuberculose</span> :</strong> miliaire<br>\n              <strong>Opportuniste :</strong> pneumocystose\n            </td>\n            <td>Agression exo- ou endogène</td>\n            <td>\n              <strong>Médicamenteuse :</strong> <span class=\"kw-ttt\">cf pneumotox.com</span><br>\n              <strong>Exacerbation de FPI</strong><br>\n              <strong>Connectivites</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Diagnostic clé</strong></td>\n            <td><span class=\"kw-imagerie\">ECG</span><br><span class=\"kw-bio\">BNP</span><br><span class=\"kw-imagerie\">ETT</span><br>Test thérapeutique aux <span class=\"kw-ttt\">diurétiques</span></td>\n            <td><span class=\"kw-bio\">Hémocultures</span><br>Antigénuries<br>Écouvillon naso-pharyngé<br><span class=\"kw-clinique\">Expectoration</span><br>LBA si immunodéprimé</td>\n            <td><span class=\"kw-bio\">GDS</span><br><span class=\"kw-bio\">Hémocultures</span><br><span class=\"kw-imagerie\">ECG</span><br><span class=\"kw-bio\">BNP</span><br><span class=\"kw-imagerie\">ETT</span></td>\n            <td>cf PID-SC<br>Rechercher cause infectieuse / cardiaque associée</td>\n          </tr>\n          <tr>\n            <td><strong>Radiologie</strong></td>\n            <td><span class=\"kw-imagerie\">Cardiomégalie</span><br><span class=\"kw-imagerie\">Opacités floues péri-hilaires</span><br><span class=\"kw-imagerie\">Épanchements pleuraux</span></td>\n            <td><span class=\"kw-imagerie\">Nodules</span><br><span class=\"kw-imagerie\">Infiltrats</span><br><span class=\"kw-imagerie\">Micronodules à contours nets</span> <em>(miliaire tuberculeuse)</em></td>\n            <td>—</td>\n            <td>cf PID-SC</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Mode d'installation subaigu / chronique (&gt;<span class=\"kw-chiffre\"> 3 semaines</span>)</h5>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Mécanisme &amp; exemples concrets</th><th>Indice diagnostique / drapeau</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Pneumopathie d'<span class=\"kw-ci\">hypersensibilité</span> (PHS)</strong></td>\n            <td><span class=\"kw-ci\">Hypersensibilité</span> retardée à des <span class=\"kw-clinique\">antigènes organiques inhalés</span> de façon répétée — foin moisi, oiseaux au domicile, jacuzzi…</td>\n            <td><span class=\"kw-alerte\">Symptômes rythmés par l'exposition</span> ; cf obj-2</td>\n          </tr>\n          <tr>\n            <td><strong>PID médicamenteuses</strong> ⭐</td>\n            <td><span class=\"kw-ttt\">méthotrexate</span> ; <span class=\"kw-ttt\">bléomycine</span> ; <span class=\"kw-ttt\">amiodarone</span> ; <span class=\"kw-ttt\">cyclophosphamide</span></td>\n            <td>Consulter <em>pneumotox.com</em> systématiquement ; <span class=\"kw-alerte\">arrêt immédiat</span> de toute drogue pneumotoxique suspecte</td>\n          </tr>\n          <tr>\n            <td><strong>PID des connectivites</strong></td>\n            <td><span class=\"kw-clinique\">PR</span> ; <span class=\"kw-clinique\">sclérodermie</span> systémique ; myosite ; dermatomyosite ; Sjögren</td>\n            <td>Auto-anticorps : <span class=\"kw-bio\">AAN</span>, <span class=\"kw-bio\">FR</span>, <span class=\"kw-bio\">anti-CCP</span>, <span class=\"kw-bio\">anti-Scl70</span>, <span class=\"kw-bio\">anti-Jo1</span> ; cf obj-8</td>\n          </tr>\n          <tr>\n            <td><strong>Pneumoconioses</strong></td>\n            <td>Particules minérales / organiques / métalliques — asbestose, silicose, bérylliose, sidérose</td>\n            <td><span class=\"kw-clinique\">Curriculum laboris</span> (durée, intensité, latence) ; cf obj-1</td>\n          </tr>\n          <tr>\n            <td><strong>Proliférations malignes</strong></td>\n            <td>\n              <strong><span class=\"kw-clinique\">Lymphangite carcinomateuse</span> :</strong> réticulations à grandes mailles polyédriques ; ATCD tumeur bronchique / mammaire / digestive / pancréatique / prostatique<br>\n              <strong><span class=\"kw-clinique\">Adénocarcinome lépidique</span> :</strong> <span class=\"kw-clinique\">dyspnée</span> + expectoration abondante claire ; <span class=\"kw-imagerie\">TDM</span> verre dépoli ± condensation<br>\n              <strong><span class=\"kw-clinique\">Lymphome pulmonaire</span></strong>\n            </td>\n            <td>Biopsies (transbronchiques, transthoraciques, éperons bronchiques)</td>\n          </tr>\n          <tr>\n            <td><strong>Médicaments pro-tussifs à connaître</strong></td>\n            <td><span class=\"kw-ttt\">amiodarone</span> ; <span class=\"kw-ttt\">amlodipine</span> ; <span class=\"kw-ttt\">interféron α/β</span> ; <span class=\"kw-ttt\">léflunomide</span> ; <span class=\"kw-ttt\">rituximab</span> ; <span class=\"kw-ttt\">statines</span> ; <span class=\"kw-ttt\">IEC</span> ; <span class=\"kw-ttt\">gliptines</span></td>\n            <td>Liste de référence à connaître ; à intégrer au questionnement systématique devant toute <span class=\"kw-clinique\">toux</span> chronique</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Réflexe EDN</strong> — devant toute PID, <strong>éliminer systématiquement</strong> : <span class=\"kw-alerte\">OAP</span> (<span class=\"kw-bio\">BNP</span>, <span class=\"kw-imagerie\">ETT</span>), cause infectieuse, cause médicamenteuse (pneumotox.com), signes de connectivite (AAN, FR, <span class=\"kw-bio\">anti-CCP</span>, <span class=\"kw-bio\">anti-Scl70</span>…), exposition professionnelle (curriculum laboris détaillé), exposition antigénique domestique (PHS).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 154 — Infection bronchopulmonaire communautaire · 192 — Pathologie <span class=\"kw-etio\">auto-immune</span> · 234 — <span class=\"kw-ci\">Insuffisance cardiaque</span> · 309 — Tumeurs du poumon · 359 — <span class=\"kw-alerte\">Détresse</span> et insuffisance respiratoire aiguë</em></p>","frequence":2},{"id":"210-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’indication des examens d’imagerie au cours d’une PID","contenu":"<p>Devant une suspicion de PID, deux examens d'imagerie structurent la démarche : la <span class=\"kw-radio\">radiographie thoracique</span> (de débrouillage) et la <span class=\"kw-radio\">TDM thoracique haute résolution</span> (pierre angulaire diagnostique).</p>\n\n      <table >\n        <thead><tr><th>Examen</th><th>Indication</th><th>Sémiologie attendue</th><th>Place</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Radiographie</span> thoracique (<span class=\"kw-imagerie\">RXT</span>)</strong></td>\n            <td><span class=\"kw-chiffre\">Première intention</span> devant toute symptomatologie respiratoire chronique inexpliquée</td>\n            <td><span class=\"kw-imagerie\">Opacités parenchymateuses diffuses</span> chez la majorité des patients ; <span class=\"kw-imagerie\">signes de fibrose</span> : <span class=\"kw-imagerie\">diminution de la taille des poumons</span>, <span class=\"kw-imagerie\">ascension des coupoles diaphragmatiques</span> ⭐</td>\n            <td><span class=\"kw-alerte\">Sensibilité limitée</span> — peut être <span class=\"kw-alerte\">normale au début</span> (notamment <span class=\"kw-clinique\">FPI</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span>-HR (haute résolution)</strong></td>\n            <td><strong>Pierre angulaire</strong> du <span class=\"kw-def\">diagnostic positif</span> et étiologique d'une PID ⭐</td>\n            <td>cf obj-5 — lésions élémentaires : micronodules, nodules, réticulations, hyperdensités (verre dépoli, condensation), rayons de miel, bronchectasies de traction, signes associés de fibrose</td>\n            <td>⭐⭐⭐ — <span class=\"kw-alerte\">L'injection de PDC n'est généralement PAS requise</span> pour l'analyse <span class=\"kw-radio\">parenchymateuse pulmonaire</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Piège QRM classique</strong> ⭐⭐⭐ — <span class=\"kw-imagerie\">TDM</span> thoracique sans injection de PDC suffit pour l'analyse d'une PID. L'injection ne s'ajoute que si suspicion de <span class=\"kw-clinique\">lésion</span> vasculaire associée (<span class=\"kw-alerte\">embolie pulmonaire</span>, HTAP, lymphangite carcinomateuse à confirmer).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 207 — Opacité intra-thoracique Adulte/Enfant</em></p>","frequence":1},{"id":"210-6","rang":"B","rubrique":"Contenu multimédia","titre":"Tomodensitométrie thoracique d’une fibrose pulmonaire idiopathique (pneumopathie interstitielle commune)","contenu":"<p>L'aspect <span class=\"kw-imagerie\">TDM</span>-HR de la <span class=\"kw-def\">fibrose pulmonaire idiopathique (FPI)</span> est celui d'une <span class=\"kw-def\">pneumopathie interstitielle commune (PIC)</span>. La sémiologie est <strong>discriminante</strong> et la reconnaître au <span class=\"kw-imagerie\">scanner</span> (sans <span class=\"kw-ttt\">biopsie</span>) suffit dans la majorité des cas typiques à poser le diagnostic.</p>\n\n      <h5>Sémiologie de la PIC sur <span class=\"kw-imagerie\">TDM</span>-HR</h5>\n      <table >\n        <thead><tr><th>Signe <span class=\"kw-imagerie\">TDM</span></th><th>Description</th><th>Valeur sémiologique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">Rayons de miel <em>(honeycombing)</em></span> ⭐</td>\n            <td>Espaces kystiques aériques limités par des parois épaissies, jointifs, en couches successives, à <span class=\"kw-imagerie\">disposition sous-pleurale</span></td>\n            <td>Signature de la PIC — destruction totale du poumon, corrélée à la fibrose idiopathique</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Réticulations intra-lobulaires</span></td>\n            <td>Mailles fines correspondant aux cloisons intralobulaires</td>\n            <td>Constantes dans la PIC</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Bronchectasies de traction</span></td>\n            <td>Dilatation des bronches par rétraction du parenchyme fibreux environnant</td>\n            <td>Signe de fibrose mature</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Distorsion architecturale</span></td>\n            <td>Désorganisation des structures broncho-vasculaires, ascension des coupoles, perte de volume</td>\n            <td>Constant en phase avancée</td>\n          </tr>\n          <tr>\n            <td><strong>Distribution</strong></td>\n            <td><span class=\"kw-imagerie\">Bibasale + sous-pleurale</span> — symétrique</td>\n            <td>Topographie pathognomonique de la PIC</td>\n          </tr>\n          <tr>\n            <td><strong>Signes négatifs attendus</strong></td>\n            <td>Pas ou peu de <span class=\"kw-imagerie\">verre dépoli</span><br>Pas de <span class=\"kw-imagerie\">nodules</span></td>\n            <td>Argument <em>contre</em> une PINS ou une PHS aiguë</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/210/tdm-pic-fpi.png\" alt=\"TDM thoracique en fenêtre parenchymateuse, coupes axiale et coronale, montrant des lésions en rayon de miel prédominant dans les régions sous-pleurales et aux bases : tableau TDM de pneumopathie interstitielle commune\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM thoracique</span>, fenêtre parenchymateuse (coupes <span class=\"kw-radio\">axiale</span> et <span class=\"kw-radio\">coronale</span>). <span class=\"kw-radio\">Lésions en rayon de miel prédominant dans les régions sous-pleurales et aux bases</span> : tableau <span class=\"kw-imagerie\">TDM</span> de <span class=\"kw-def\">pneumopathie interstitielle commune (PIC)</span>, évoquant une <span class=\"kw-def\">fibrose pulmonaire idiopathique (FPI)</span> en l'absence de cause retrouvée. Source : banque imagerie « Imagerie à connaître » (item 210).</figcaption>\n      </figure>\n\n      <h5>Comparatif PIC <span class=\"kw-bio\">vs</span> PINS (le plus important différentiel)</h5>\n      <table >\n        <thead><tr><th></th><th>PIC (FPI typique)</th><th>PINS</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Sémiologie dominante</strong></td>\n            <td><span class=\"kw-imagerie\">Rayons de miel</span><br><span class=\"kw-imagerie\">Réticulations intra-lobulaires</span><br><span class=\"kw-imagerie\">Bronchectasies de traction</span></td>\n            <td><span class=\"kw-imagerie\">Verre dépoli ++</span><br>Réticulations à mailles fines<br>Bronchectasies de traction</td>\n          </tr>\n          <tr>\n            <td><strong>Distribution</strong></td>\n            <td>Bibasale<br><span class=\"kw-imagerie\">Sous-pleurale</span></td>\n            <td>Plutôt <span class=\"kw-imagerie\">péri-bronchovasculaire</span></td>\n          </tr>\n          <tr>\n            <td><strong>Signes négatifs</strong></td>\n            <td>Pas ou peu de verre dépoli<br>Pas de nodules</td>\n            <td>Pas de destruction de l'architecture</td>\n          </tr>\n          <tr>\n            <td><strong>Étiologies classiques</strong></td>\n            <td><strong>FPI +++</strong><br>PHS chronique<br>Asbestose</td>\n            <td>\n              <strong>Idiopathique</strong><br>\n              <strong><span class=\"kw-clinique\">Connectivites</span> :</strong> <span class=\"kw-clinique\">PR</span> ; sclérodermie ; myosite ; Sjögren<br>\n              <strong>PHS</strong> aiguë / subaiguë<br>\n              <strong><span class=\"kw-ttt\">Médicaments</span> :</strong> <span class=\"kw-ttt\">méthotrexate</span> ; bléomycine ; <span class=\"kw-ttt\">amiodarone</span> ; <span class=\"kw-ttt\">cyclophosphamide</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-alerte\">Drapeau rouge</span> à connaître</strong> ⭐ — chez un sujet âgé (&gt;<span class=\"kw-chiffre\"> 50 ans</span>) avec <span class=\"kw-clinique\">crépitants velcro basaux</span> + <span class=\"kw-clinique\">hippocratisme digital</span> + <span class=\"kw-imagerie\">TDM</span>-HR PIC typique bibasale sous-pleurale, le diagnostic de FPI peut être posé <strong>sans <span class=\"kw-ttt\">biopsie</span></strong>. La biopsie chirurgicale n'est requise qu'en cas de présentation non typique.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 207 — Opacité intra-thoracique Adulte/Enfant · 208 — <span class=\"kw-ci\">Insuffisance respiratoire</span> chronique</em></p>","frequence":3},{"id":"210-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la stratégie diagnostique initiale devant une PID","contenu":"<p>La stratégie diagnostique devant une PID subaiguë ou chronique (&gt;<span class=\"kw-chiffre\"> 3 semaines</span>) suit une <strong>séquence hiérarchisée en 8 paliers</strong>. À chaque palier, si le diagnostic est posé → on s'arrête ; sinon → on passe au palier suivant.</p>\n\n      <table >\n        <thead><tr><th>Palier</th><th>Examen / démarche</th><th>Cible diagnostique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1</strong></td><td><span class=\"kw-clinique\">Histoire clinique</span> — expositions environnementales ; professionnelles ; médicamenteuses (pneumotox.com)</td><td>PHS ; pneumoconiose ; médicaments</td></tr>\n          <tr><td><strong>2</strong></td><td><span class=\"kw-clinique\">Examen clinique</span> — signes extra-thoraciques de connectivite (arthralgies, Raynaud, syndrome sec, <span class=\"kw-clinique\">sclérodactylie</span>, mains de mécanicien, <span class=\"kw-bio\">BU</span>)</td><td><span class=\"kw-clinique\">PR</span>, sclérodermie, myosite, Sjögren, vascularites</td></tr>\n          <tr><td><strong>3</strong></td><td><span class=\"kw-radio\">TDM thoracique haute résolution</span></td><td>Profil radiologique discriminant (PIC, PINS, <span class=\"kw-clinique\">sarcoïdose</span>, silicose…)</td></tr>\n          <tr><td><strong>4</strong></td><td><span class=\"kw-bio\">Biologie sanguine</span> — cf obj-8</td><td>Connectivites, <span class=\"kw-clinique\">sarcoïdose</span>, vascularites, hémorragie alvéolaire</td></tr>\n          <tr><td><strong>5</strong></td><td><span class=\"kw-bio\">Fibroscopie bronchique + LBA</span> ± <span class=\"kw-bio\">biopsies bronchiques d'éperons</span></td><td><span class=\"kw-clinique\">Sarcoïdose</span>, lymphangite carcinomateuse, infections (<span class=\"kw-etio\">tuberculose</span>, pneumocystose), hémorragie alvéolaire</td></tr>\n          <tr><td><strong>6</strong></td><td><span class=\"kw-bio\">Biopsies transbronchiques</span> ± <span class=\"kw-bio\">biopsies ADP médiastinales</span></td><td>4 PID seulement <em>(risque <span class=\"kw-clinique\">hémoptysie</span> / pneumothorax)</em> :<br><span class=\"kw-alerte\">Sarcoïdose stades II-III-IV</span> <em>(<span class=\"kw-def\">classification</span> radiologique de Scadding)</em><br><span class=\"kw-alerte\">Lymphangite carcinomateuse</span><br><span class=\"kw-alerte\">Pneumopathie organisée</span><br><span class=\"kw-alerte\">Miliaire tuberculeuse</span></td></tr>\n          <tr><td><strong>7</strong></td><td><span class=\"kw-clinique\">Discussion multidisciplinaire (DMD)</span></td><td>Consensus entre pneumologue, radiologue, anatomopathologiste</td></tr>\n          <tr><td><strong>8</strong></td><td><span class=\"kw-alerte\">Biopsie pulmonaire vidéo-chirurgicale / cryobiopsie transbronchique</span></td><td>Recours après échec DMD ; uniquement si impact attendu sur la PEC</td></tr>\n        </tbody>\n      </table>\n\n      <h5>Tableau étiologique discriminant (<span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>5</span> g</span>randes causes)</h5>\n      <table >\n        <thead><tr><th>Critère</th><th><span class=\"kw-clinique\">Sarcoïdose</span></th><th>PHS</th><th>Connectivites</th><th>FPI</th><th>Pneumoconioses</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td><span class=\"kw-clinique\">Sujet jeune (&lt; 40 ans)</span></td>\n            <td>Exposition antigénique <em>(foin ; oiseaux ; jacuzzi)</em></td>\n            <td><span class=\"kw-clinique\">Sclérodermie</span> ; lupus…</td>\n            <td><span class=\"kw-clinique\">Sujet âgé (&gt; 50 ans)</span></td>\n            <td>Exposition professionnelle <em>(durée ; intensité ; latence)</em></td>\n          </tr>\n          <tr>\n            <td><strong>Clinique</strong></td>\n            <td>Signes extra-thoraciques <em>(cutanés ; ganglionnaires ; oculaires)</em></td>\n            <td><span class=\"kw-clinique\">Symptômes rythmés par l'exposition</span><br>Syndrome grippal <span class=\"kw-chiffre\">4–10 h</span> après <span class=\"kw-def\">contact</span></td>\n            <td>Manifestations de la connectivite sous-jacente</td>\n            <td>Signes pulmonaires au premier plan<br><span class=\"kw-clinique\">Crépitants velcro</span><br><span class=\"kw-clinique\">Hippocratisme digital</span></td>\n            <td>Absents ou discrets</td>\n          </tr>\n          <tr>\n            <td><strong>Biologie</strong></td>\n            <td>↑ ECA</td>\n            <td>Précipitines anti-actinomycètes ou anti-déjections d'oiseaux</td>\n            <td>Auto-anticorps <em>(AAN ; FR ; <span class=\"kw-bio\">anti-CCP</span> ; <span class=\"kw-bio\">anti-Scl70</span>…)</em></td>\n            <td>Normale / immuno négative</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span>-HR</strong></td>\n            <td>Micronodules <span class=\"kw-imagerie\">supérieurs</span><br>ADP médiastinales</td>\n            <td>Micronodules<br>Verre dépoli</td>\n            <td>Verre dépoli<br>± Rayons de miel</td>\n            <td><span class=\"kw-imagerie\">Réticulations</span><br><span class=\"kw-imagerie\">Rayons de miel</span><br>Topographie <span class=\"kw-imagerie\">sous-pleural bibasal</span></td>\n            <td>\n              <strong>Silicose :</strong> micronodules supérieurs ; ADP « coquille d'œuf »<br>\n              <strong>Asbestose :</strong> opacités basales ; plaques pleurales\n            </td>\n          </tr>\n          <tr>\n            <td><strong>LBA</strong></td>\n            <td>Lymphocytose <span class=\"kw-bio\">CD4⁺</span> <em>(<span class=\"kw-chiffre\">CD4</span>/CD8 &gt; 3)</em></td>\n            <td>Lymphocytose <span class=\"kw-bio\">CD8⁺</span> <em>(<span class=\"kw-chiffre\">CD4</span>/CD8 &lt; 1)</em></td>\n            <td>Lymphocytose ou neutrophilie</td>\n            <td>Neutrophilie<br>± Éosinophilie</td>\n            <td>\n              <strong>Silicose :</strong> alvéolite macrophagique ; corps biréfringents<br>\n              <strong>Asbestose :</strong> alvéolite neutrophilique ; corps asbestosiques\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Histologie</span></strong></td>\n            <td>Granulomes épithélioïdes g<span class=\"kw-chiffre\">iga</span>nto-cellulaires <strong>sans <span class=\"kw-clinique\">nécrose</span> caséeuse</strong></td>\n            <td>Granulomes histiocytaires mal formés<br>Organisation conjonctive endoluminale</td>\n            <td>PINS<br>PIC<br>± POC, DAD</td>\n            <td>PIC</td>\n            <td>\n              <strong>Silicose :</strong> <span class=\"kw-clinique\">nodule</span> fibro-hyalin<br>\n              <strong>Asbestose :</strong> PIC + corps asbestosiques\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>À retenir absolument</strong> — la <span class=\"kw-clinique\">FPI est un diagnostic d'EXCLUSION</span>. Avant de la retenir : éliminer PHS chronique (précipitines, LBA <span class=\"kw-chiffre\">CD8</span>⁺), connectivites (immuno systématique), asbestose (curriculum laboris + plaques pleurales), médicaments pneumotoxiques (pneumotox.com). C'est tout l'enjeu des paliers 1 à 5.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 192 — Pathologie <span class=\"kw-etio\">auto-immune</span> · 211 — <span class=\"kw-clinique\">Sarcoïdose</span> · 309 — Tumeurs du poumon</em></p>","frequence":4},{"id":"210-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’intérêt des épreuves fonctionnelles respiratoires (EFR) pour le diagnostic et le suivi des PID","contenu":"<p><span class=\"kw-clinique\">Les</span> EFR <strong>ne posent jamais le <span class=\"kw-def\">diagnostic étiologique</span></strong> d'une PID — mais elles sont essentielles pour <span class=\"kw-clinique\">apprécier la sévérité</span> et <span class=\"kw-clinique\">suivre l'évolution</span>.</p>\n\n      <table >\n        <thead><tr><th>Paramètre EFR</th><th>Profil typique dans une PID</th><th>Valeur sémiologique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Gazométrie</span> artérielle</strong></td>\n            <td>\n              <strong>Repos :</strong> initialement <span class=\"kw-bio\">normale</span><br>\n              <strong>Effort :</strong> <span class=\"kw-alerte\">anormale</span> — hypoxémie avec normo- ou hypocapnie\n            </td>\n            <td>Sensibilité supérieure du <span class=\"kw-bio\">GDS</span> à l'effort par rapport au repos en phase précoce</td>\n          </tr>\n          <tr>\n            <td><strong>Trouble ventilatoire restrictif (TVR) pur</strong></td>\n            <td>\n              <strong><span class=\"kw-bio\">CPT</span> :</strong> <span class=\"kw-bio\">&lt; 80 %</span><br>\n              <strong><span class=\"kw-bio\">CV</span> et <span class=\"kw-bio\">VEMS</span> :</strong> diminution homogène<br>\n              <strong><span class=\"kw-bio\">Tiffeneau (VEMS/CV)</span> :</strong> <span class=\"kw-bio\">&gt; 70 %</span> <em>(rapport conservé)</em>\n            </td>\n            <td>Signature fonctionnelle des PID</td>\n          </tr>\n          <tr>\n            <td><strong>DLCO (diffusion CO)</strong></td>\n            <td><span class=\"kw-bio\">DLCO &lt; 70 %</span></td>\n            <td>Altération de la fonction échangeur — précoce et sensible</td>\n          </tr>\n          <tr>\n            <td><strong>Test de marche <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>6</span> min</span>utes</strong></td>\n            <td><span class=\"kw-clinique\">Hypoxémie à l'effort</span>, souvent absente au repos</td>\n            <td>Utile pour le <span class=\"kw-def\">suivi</span> et l'indication d'<span class=\"kw-ttt\">oxygénothérapie</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège fumeur</strong> — un <span class=\"kw-bio\">TVO associé</span> est possible chez le tabagique chronique (fibrose + emphysème = <span class=\"kw-clinique\">combined pulmonary fibrosis and emphysema, CPFE</span>). Le rapport de <span class=\"kw-bio\">Tiffeneau</span> peut alors être faussement conservé : interpréter en valeur absolue (<span class=\"kw-bio\">CV ↓</span> + <span class=\"kw-bio\">VEMS ↓</span> proportionnels) et corréler à la <span class=\"kw-bio\">DLCO</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 208 — <span class=\"kw-ci\">Insuffisance respiratoire</span> chronique · 209 — BPCO</em></p>","frequence":2},{"id":"210-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principaux examens biologiques dont les examens immunologiques à effectuer devant une PID","contenu":"<p>Le bilan <span class=\"kw-ttt\">biologique</span> devant une PID est ciblé : il vise à éliminer <span class=\"kw-clinique\">les</span> causes secondaires fréquentes (cardiaque, infectieuse, <span class=\"kw-etio\">auto-immune</span>) et à orienter vers les grandes étiologies (sarcoïdose, connectivites, vascularites, PHS).</p>\n\n      <table >\n        <thead><tr><th>Examen</th><th>Cible diagnostique</th><th>Anomalie évocatrice</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span></strong></td>\n            <td>Inflammation ; hyperéosinophilie ; lymphopénie</td>\n            <td>\n              <strong><span class=\"kw-bio\">Hyperéosinophilie</span> :</strong> pneumopathie à <span class=\"kw-bio\">éosinophiles</span><br>\n              <strong><span class=\"kw-bio\">Lymphopénie</span> :</strong> <span class=\"kw-clinique\">sarcoïdose</span> ; immunodépression ; traitement <span class=\"kw-ttt\">immunosuppresseur</span><br>\n              <strong><span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">inflammatoire</span></span> :</strong> infection ; connectivite\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">BNP</span> / <span class=\"kw-bio\">NT-proBNP</span></strong></td>\n            <td><span class=\"kw-clinique\">Insuffisance cardiaque gauche</span> (<span class=\"kw-alerte\">OAP</span> comme cause aiguë de PID)</td>\n            <td>Élevé → orienter vers <span class=\"kw-imagerie\">ETT</span> et test <span class=\"kw-ttt\">diurétique</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Créatininémie</span></strong></td>\n            <td><span class=\"kw-ci\">Insuffisance rénale</span> (vascularites pulmo-rénales, médicaments)</td>\n            <td>↑ → rechercher <span class=\"kw-bio\">ANCA</span>, <span class=\"kw-bio\">BU</span> systématique</td>\n          </tr>\n          <tr>\n            <td><strong>Précipitines sériques (<span class=\"kw-chiffre\">IgG</span>)</strong></td>\n            <td><span class=\"kw-clinique\">Pneumopathies d'hypersensibilité</span></td>\n            <td><span class=\"kw-bio\">Anticorps anti-actinomycètes</span> (foin) ou anti-déjections d'oiseaux ; valeur d'orientation, n'affirme ni n'exclut</td>\n          </tr>\n          <tr>\n            <td><strong>ECA · <span class=\"kw-bio\">calcémie</span> · calciurie</strong></td>\n            <td><span class=\"kw-clinique\">Sarcoïdose</span></td>\n            <td>\n              <span class=\"kw-bio\">↑ ECA</span><br>\n              <span class=\"kw-bio\">Hypercalcémie</span><br>\n              ± <span class=\"kw-bio\">Hypercalciurie</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>FR · <span class=\"kw-bio\">anti-CCP</span> · AAN · anti-ADN</strong></td>\n            <td><span class=\"kw-clinique\">Connectivites</span> <em>(<span class=\"kw-clinique\">PR</span> ; lupus ; sclérodermie ; Sjögren ; myosite ; dermatomyosite)</em></td>\n            <td>\n              <strong><span class=\"kw-clinique\">Sclérodermie</span> :</strong> <span class=\"kw-bio\">anti-Scl70</span><br>\n              <strong><span class=\"kw-clinique\">Sjögren</span> :</strong> <span class=\"kw-bio\">anti-Ro / anti-La</span><br>\n              <strong><span class=\"kw-clinique\">Myosite anti-synthétase</span> :</strong> <span class=\"kw-bio\">anti-Jo1</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">ANCA</span> (<span class=\"kw-bio\">c-ANCA</span>, p-ANCA)</strong></td>\n            <td><span class=\"kw-clinique\">Vascularites des petits vaisseaux</span> (<span class=\"kw-clinique\">GPA</span>, MPA, GEPA)</td>\n            <td>Positivité → contexte d'hémorragie intra-alvéolaire ou de glomérulonéphrite associée</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Astuce diagnostique LBA</strong> — au-delà du bilan sanguin, le LBA apporte parfois la <span class=\"kw-bio\">certitude diagnostique</span> :\n        <ul>\n          <li><strong>Tumeur :</strong> cellules malignes</li>\n          <li><strong>Infection :</strong> mycobactéries ; <em>Pneumocystis jirovecii</em></li>\n          <li><strong>Hémorragie alvéolaire :</strong> sidérophages &gt;<span class=\"kw-chiffre\"> 20 %</span> + <span class=\"kw-def\">score</span> de Golde &gt; 100</li>\n          <li><strong>Protéinose alvéolaire :</strong> aspect laiteux PAS+</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 192 — Pathologie <span class=\"kw-etio\">auto-immune</span> · 211 — <span class=\"kw-clinique\">Sarcoïdose</span></em></p>","frequence":3}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> <span class=\"kw-alerte\">PID d'installation aiguë</span> (<span class=\"kw-chiffre\">&lt; 3 semaines</span>) = <span class=\"kw-alerte\">urgence</span> ; <span class=\"kw-alerte\">détresse respiratoire</span> = urgence vitale<br><strong>Fenêtre :</strong> PID aiguë <span class=\"kw-clinique\">fébrile</span> → lecture du <span class=\"kw-bio\">LBA</span> faite en priorité<br><strong>1er geste :</strong> éliminer l'<span class=\"kw-etio\">OAP</span> cardiogénique ; <span class=\"kw-ttt\">arrêt immédiat des drogues pneumotoxiques</span> ; <span class=\"kw-ttt\">O₂ à haut débit</span></p>","hospit":"<p><strong>Réa :</strong> <span class=\"kw-alerte\">détresse respiratoire</span> → <span class=\"kw-ttt\">transfert en réanimation</span> + <span class=\"kw-ttt\">O₂ haut débit</span> ± <span class=\"kw-ttt\">assistance ventilatoire</span><br><strong>PID aiguë fébrile :</strong> <span class=\"kw-bio\">LBA</span> réalisé une fois la <span class=\"kw-etio\">cause cardiaque</span> éliminée ; indiqué dans toute PID de l'<span class=\"kw-clinique\">immunodéprimé</span></p>","redflags":"<ul><li><span class=\"kw-alerte\">Détresse / insuffisance respiratoire aiguë</span> → transfert en <span class=\"kw-alerte\">réanimation</span></li><li><span class=\"kw-clinique\">Hypoxémie</span> (d'abord à l'effort, puis au repos)</li><li><span class=\"kw-alerte\">PID aiguë</span> (<span class=\"kw-chiffre\">&lt; 3 semaines</span>), surtout si <span class=\"kw-clinique\">fébrile</span></li><li>Signes d'<span class=\"kw-etio\">insuffisance cardiaque gauche</span> (<span class=\"kw-clinique\">expectoration mousseuse</span>) : <span class=\"kw-alerte\">OAP</span> à éliminer en priorité</li><li><span class=\"kw-clinique\">Hippocratisme digital</span> + <span class=\"kw-clinique\">crépitants velcro</span> des bases → évoquent une <span class=\"kw-etio\">fibrose pulmonaire</span></li><li><span class=\"kw-radio\">Rayon de miel</span> à la <span class=\"kw-imagerie\">TDM</span> (aspect PIC) = destruction architecturale ; <span class=\"kw-etio\">FPI</span> de <span class=\"kw-def\">pronostic</span> sombre (médiane <span class=\"kw-chiffre\">3 ans</span> sans traitement)</li><li><span class=\"kw-alerte\">Fibrose pulmonaire progressive</span> : aggravation clinique/fonctionnelle/radiologique <span class=\"kw-chiffre\">≤ 1 an</span> malgré traitement</li></ul>","principes":"<p><strong>PEC d'<span class=\"kw-alerte\">urgence</span> d'une PID aiguë</strong></p><p>Toujours suspecter et éliminer l'<span class=\"kw-alerte\">OAP</span> en premier (cause la plus fréquente)</p><ul><li><span class=\"kw-alerte\">Détresse respiratoire</span> → <span class=\"kw-ttt\">transfert en réanimation</span></li><li><span class=\"kw-ttt\">Arrêt immédiat</span> de toute <span class=\"kw-ttt\">drogue pneumotoxique</span> (pneumotox.com)</li><li><span class=\"kw-ttt\">Oxygénothérapie à haut débit</span> ± <span class=\"kw-ttt\">assistance ventilatoire</span></li><li>Doute sur <span class=\"kw-etio\">insuffisance cardiaque</span> → <span class=\"kw-ttt\">diurétiques</span></li><li><span class=\"kw-clinique\">Fièvre</span> → <span class=\"kw-ttt\">anti-infectieux probabiliste</span> : <span class=\"kw-etio\">pneumocoque</span> + intracellulaires (<span class=\"kw-clinique\">PAC</span> grave) ; <span class=\"kw-etio\">Pneumocystis jirovecii</span> si immunodéprimé ; <span class=\"kw-etio\">M. tuberculosis</span> si imagerie évocatrice</li></ul><p><strong>Stratégie diagnostique étiologique (PID subaiguë/chronique)</strong></p><p>À chaque étape : diagnostic posé → on s'arrête ; sinon → étape suivante</p><ul><li>1. <span class=\"kw-clinique\">Histoire clinique</span> : expositions environnementales, professionnelles, médicamenteuses</li><li>2. <span class=\"kw-clinique\">Examen clinique</span> : signes de connectivite, signes extra-thoraciques de <span class=\"kw-clinique\">sarcoïdose</span></li><li>3. <span class=\"kw-imagerie\">Scanner thoracique haute résolution</span></li><li>4. <span class=\"kw-bio\">Biologie sanguine</span> orientée</li><li>5. <span class=\"kw-ttt\">Fibroscopie + LBA</span> ± biopsies bronchiques (si <span class=\"kw-clinique\">sarcoïdose</span> / lymphangite carcinomateuse)</li><li>6. <span class=\"kw-ttt\">Biopsies trans-bronchiques</span> + biopsies d'ADP médiastinales</li><li>7. <span class=\"kw-ttt\">Discussion multidisciplinaire</span></li><li>8. <span class=\"kw-ttt\">Biopsie pulmonaire vidéo-chirurgicale</span> en dernier recours</li></ul><p><strong>Examens complémentaires clés</strong></p><ul><li><span class=\"kw-imagerie\">TDM thoracique</span> = pierre angulaire ; <span class=\"kw-ttt\">injection de PDC</span> généralement non requise pour l'analyse parenchymateuse</li><li><span class=\"kw-bio\">EFR</span> : aucune valeur étiologique, apprécie la sévérité et utile au <span class=\"kw-def\">suivi</span> — <span class=\"kw-def\">TVR pur</span> (<span class=\"kw-chiffre\">CPT &lt; 80%</span>, <span class=\"kw-chiffre\">VEMS/CV &gt; 70%</span>), <span class=\"kw-chiffre\">DLCO &lt; 70%</span>, hypoxémie à l'effort</li><li><span class=\"kw-bio\">LBA</span> : examen clé des PID aiguës fébriles ; recours à l'<span class=\"kw-bio\">histologie</span> dans <span class=\"kw-chiffre\">&lt; 15%</span> des PID</li><li>Bilan bio étiologique : <span class=\"kw-bio\">NFS/CRP</span>, <span class=\"kw-bio\">BNP</span>, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">précipitines</span> (PHS), <span class=\"kw-bio\">ECA/calcémie/calciurie</span> (<span class=\"kw-clinique\">sarcoïdose</span>), <span class=\"kw-bio\">FR/anti-CCP/AAN/anti-ADN</span> (connectivites), <span class=\"kw-bio\">ANCA</span> (vascularites)</li></ul><p><strong>Traitements spécifiques</strong></p><ul><li><span class=\"kw-etio\">Fibrose pulmonaire idiopathique</span> : <span class=\"kw-ttt\">anti-fibrosants</span> (ralentissent le déclin, réduisent <span class=\"kw-clinique\">les</span> exacerbations)</li><li><span class=\"kw-etio\">PINS</span> : <span class=\"kw-ttt\">immunosuppresseurs</span> ± <span class=\"kw-ttt\">anti-fibrosants</span></li><li><span class=\"kw-etio\">Pneumopathie d'hypersensibilité</span> : <span class=\"kw-ttt\">éviction de l'antigène</span> (forme aiguë souvent réversible)</li><li><span class=\"kw-etio\">Fibrose pulmonaire progressive</span> : <span class=\"kw-ttt\">anti-fibrosants</span></li></ul>","suivi":"<p><strong>EFR :</strong> apprécient la sévérité et sont utiles au <span class=\"kw-ttt\">suivi</span> (<span class=\"kw-chiffre\">CPT</span>, <span class=\"kw-chiffre\">DLCO</span>, test de marche de <span class=\"kw-chiffre\">6 min</span>)<br><strong><span class=\"kw-clinique\">Évolution</span> :</strong> surveiller le passage en <span class=\"kw-alerte\">fibrose pulmonaire progressive</span> (aggravation clinique/fonctionnelle/radiologique <span class=\"kw-chiffre\">≤ 1 an</span>)<br><strong><span class=\"kw-def\">Pronostic</span> :</strong> <span class=\"kw-etio\">FPI</span> → <span class=\"kw-ci\">insuffisance respiratoire</span> terminale, médiane de survie <span class=\"kw-chiffre\">3 ans</span> sans traitement ; <span class=\"kw-etio\">asbestose</span> → insuffisance respiratoire chronique constante</p>"},"liensGlobaux":[{"href":"https://cep-1f48c.kxcdn.com/wp-content/uploads/2023/07/ITEM_210_PNEUMOPATHIES_INTERSTITIELLES_DIFFUSES_2023.pdf","label":"Collège (CEP) — Item 210 pneumopathies interstitielles diffuses 2023"},{"href":"https://radiopaedia.org/articles/interstitial-lung-pattern-radiograph","label":"Radiopaedia : Interstitial lung pattern radiograph"},{"href":"https://www.sit-radiologie.fr/juniors-0/2eme-cycle-fiche-lisa/savoir-diagnostiquer-un-syndrome-interstitiel","label":"SIT radiologie — Savoir diagnostiquer un syndrome interstitiel"},{"href":"https://www.decas.univ-nantes.fr/certif2008/SemioImagerie2008/I-.-4-.-2-syndrome-interstitiel.htm","label":"I . 4 . 2 syndrome interstitiel"},{"href":"https://radiopaedia.org/articles/interstitial-lung-disease","label":"Radiopaedia : Interstitial lung disease"},{"href":"https://radiopaedia.org/articles/usual-interstitial-pneumonia","label":"Radiopaedia : Usual interstitial pneumonia"},{"href":"https://radiopaedia.org/articles/non-specific-interstitial-pneumonia-1","label":"Radiopaedia : Non specific interstitial pneumonia 1"},{"href":"https://radiopaedia.org/articles/hypersensitivity-pneumonitis","label":"Radiopaedia : Hypersensitivity pneumonitis"},{"href":"https://radiopaedia.org/articles/pneumoconiosis","label":"Radiopaedia : Pneumoconiosis"},{"href":"https://radiopaedia.org/articles/idiopathic-pulmonary-fibrosis","label":"Radiopaedia : Idiopathic pulmonary fibrosis"},{"href":"http://pneumotox.com/","label":"pneumotox.com"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"PID confirmée à la TDM thoracique — Orienter selon le délai d'installation","detail":"<h4>CAT — orientation d'une PID selon le délai d'installation — PID confirmée à la <span class=\"kw-imagerie\">TDM</span> : distinguer aiguë (&lt; 3 sem) et subaiguë/chronique (&gt; 3 sem)</h4>","branches":[{"to":"q-delai","label":"PID confirmée","color":"blue"}]},{"id":"q-delai","kind":"decision","label":"Délai d'installation de la PID ?","branches":[{"to":"q-aigu-gravite","label":"Aiguë &lt; 3 semaines","color":"red"},{"to":"q-chronique-bio","label":"Subaiguë / chronique &gt; 3 semaines","color":"amber"}]},{"id":"q-aigu-gravite","kind":"decision","label":"Signes de détresse respiratoire ? — PID aiguë","branches":[{"to":"t-rea","label":"Oui","color":"red"},{"to":"q-aigu-fievre","label":"Non","color":"amber"}]},{"id":"t-rea","kind":"terminal","label":"Transfert en réanimation","color":"red","detail":"<h4>Conduite (<span class=\"kw-alerte\">urgence</span>)</h4><ul><li><span class=\"kw-ttt\">Transfert en réanimation</span></li><li><span class=\"kw-ttt\">Oxygénothérapie à haut débit</span> ± <span class=\"kw-ttt\">assistance ventilatoire</span></li><li><span class=\"kw-ttt\">Arrêt immédiat</span> de toute <span class=\"kw-ttt\">drogue pneumotoxique</span> (pneumotox.com)</li><li>Doute sur <span class=\"kw-etio\">insuffisance cardiaque</span> → <span class=\"kw-ttt\">diurétiques</span></li><li><span class=\"kw-clinique\">Fièvre</span> → <span class=\"kw-ttt\">anti-infectieux probabiliste</span></li></ul>"},{"id":"q-aigu-fievre","kind":"decision","label":"Fièvre ? — PID aiguë sans détresse","branches":[{"to":"t-infection","label":"Oui","color":"amber"},{"to":"t-noninfect","label":"Non","color":"blue"}]},{"id":"t-infection","kind":"terminal","label":"Cause infectieuse probable","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Anti-infectieux probabiliste</span> couvrant <span class=\"kw-etio\">pneumocoque</span> + <span class=\"kw-etio\">germes intracellulaires</span> (<span class=\"kw-clinique\">PAC</span> grave)</li><li>Immunodépression + imagerie compatible → couvrir <span class=\"kw-etio\">Pneumocystis jirovecii</span></li><li>Imagerie évocatrice → couvrir <span class=\"kw-etio\">Mycobacterium tuberculosis</span></li><li><span class=\"kw-ttt\">Arrêt des drogues pneumotoxiques</span></li></ul><h4>Confirmation</h4><ul><li><span class=\"kw-bio\">LBA</span> = examen clé de la PID aiguë fébrile (après élimination de la cause cardiaque)</li><li><span class=\"kw-imagerie\">RXT</span>, <span class=\"kw-bio\">hémocultures</span>, antigénuries/antigénémies, écouvillon naso-pharyngé, <span class=\"kw-clinique\">expectoration</span></li></ul><h4>Renvoi</h4><ul><li>Item 154 (Infections broncho-pulmonaires)</li></ul>"},{"id":"t-noninfect","kind":"terminal","label":"Cause non infectieuse — éliminer l'OAP en priorité","color":"blue","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-etio\">OAP cardiogénique</span> doit toujours être suspecté (fréquence) : à éliminer en premier</li><li>Doute → <span class=\"kw-ttt\">test thérapeutique aux diurétiques</span></li><li><span class=\"kw-ttt\">Arrêt des drogues pneumotoxiques</span></li><li>Autres causes : <span class=\"kw-etio\">SDRA</span>, exacerbation de <span class=\"kw-etio\">PID subaiguë/chronique</span>, <span class=\"kw-etio\">pneumopathie médicamenteuse</span>, <span class=\"kw-etio\">hémorragie intra-alvéolaire</span>, <span class=\"kw-etio\">pneumopathie aiguë à éosinophiles</span></li></ul><h4>Confirmation</h4><ul><li><span class=\"kw-alerte\">OAP</span> : <span class=\"kw-bio\">ECG</span>, <span class=\"kw-bio\">BNP</span>, <span class=\"kw-imagerie\">ETT</span></li><li><span class=\"kw-alerte\">SDRA</span> : <span class=\"kw-bio\">GDS</span>, <span class=\"kw-bio\">hémocultures</span>, <span class=\"kw-imagerie\">ECG</span>, <span class=\"kw-bio\">BNP</span>, <span class=\"kw-imagerie\">ETT</span></li><li><span class=\"kw-bio\">LBA</span> réalisé une fois la cause cardiaque éliminée</li></ul>"},{"id":"q-chronique-bio","kind":"decision","label":"Diagnostic obtenu après contexte + examen + TDM-HR + biologie ? — PID subaiguë / chronique","branches":[{"to":"t-diag-noninvasif","label":"Oui","color":"green"},{"to":"t-lba-biopsie","label":"Non","color":"amber"}]},{"id":"t-diag-noninvasif","kind":"terminal","label":"Diagnostic retenu — pas d'exploration invasive","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-def\">Diagnostic étiologique</span> retenu sur <span class=\"kw-clinique\">contexte</span> + <span class=\"kw-clinique\">examen clinique</span> + <span class=\"kw-imagerie\">TDM-HR</span> + <span class=\"kw-bio\">biologie</span></li><li>Pas de recours à la <span class=\"kw-imagerie\">fibroscopie</span> ni à l'<span class=\"kw-bio\">histologie</span> (histologie dans <span class=\"kw-chiffre\">&lt; 15%</span> des PID)</li></ul><h4>Éléments d'orientation</h4><ul><li><span class=\"kw-clinique\">Histoire clinique</span> : expositions environnementales, professionnelles, médicamenteuses</li><li><span class=\"kw-clinique\">Examen clinique</span> : signes de <span class=\"kw-etio\">connectivite</span>, signes extra-thoraciques de <span class=\"kw-etio\">sarcoïdose</span></li><li><span class=\"kw-imagerie\">Scanner thoracique haute résolution</span></li><li><span class=\"kw-bio\">Biologie sanguine</span> orientée (précipitines, ECA, FR/<span class=\"kw-bio\">anti-CCP</span>/AAN, <span class=\"kw-bio\">ANCA</span>…)</li></ul>"},{"id":"t-lba-biopsie","kind":"terminal","label":"Diagnostic non obtenu — explorations invasives étagées","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Fibroscopie bronchique + LBA</span></li><li>± <span class=\"kw-ttt\">Biopsies bronchiques</span> si suspicion de <span class=\"kw-etio\">sarcoïdose</span> ou de <span class=\"kw-etio\">lymphangite carcinomateuse</span></li><li><span class=\"kw-ttt\">Biopsies trans-bronchiques</span> + biopsies d'ADP médiastinales</li><li><span class=\"kw-ttt\">Discussion multidisciplinaire</span></li><li><span class=\"kw-ttt\">Biopsie pulmonaire vidéo-chirurgicale</span> en dernier recours</li></ul><h4>Précautions</h4><ul><li>Biopsies transbronchiques réservées à 4 PID (<span class=\"kw-etio\">sarcoïdose</span>, <span class=\"kw-etio\">lymphangite carcinomateuse</span>, <span class=\"kw-etio\">pneumopathie organisée</span>, <span class=\"kw-etio\">miliaire tuberculeuse</span>) : risque d'<span class=\"kw-alerte\">hémoptysie</span> et de <span class=\"kw-alerte\">pneumothorax</span></li><li><span class=\"kw-ttt\">Biopsie</span> chirurgicale après DMD si PID non typique et impact sur la PEC</li></ul><h4>Renvoi</h4><ul><li>Item 211 (<span class=\"kw-clinique\">Sarcoïdose</span>)</li></ul>"}]},"cards":[{"i":"4f51b8141991","n":210,"o":"210-1","u":"Définition","t":"Connaître la définition des pneumopathies interstitielles diffuses (PID), connaître les grandes catégories de PID","q":"Quelle est la définition des pneumopathies interstitielles diffuses (PID) ?","a":"<p>Les pneumopathies interstitielles diffuses (PID), également appelées pneumopathies infiltratives diffuses, regroupent un ensemble <strong>hétérogène d'affections</strong> qui touchent l'<strong>interstitium pulmonaire</strong>.</p>"},{"i":"62b425345437","n":210,"o":"210-1","u":"Définition","t":"Connaître la définition des pneumopathies interstitielles diffuses (PID), connaître les grandes catégories de PID","q":"Citer des exemples de pneumopathies interstitielles diffuses secondaires (à cause connue).","a":"<p>Les PID secondaires incluent notamment :</p><ul><li>Des causes <strong>cardiaques</strong> (ex: insuffisance cardiaque gauche).</li><li>Des causes <strong>infectieuses</strong> (ex: tuberculose, viroses dont SARS-CoV-2, pneumocystose, champignons).</li><li>Des causes <strong>médicamenteuses</strong> (ex: méthotrexate, bléomycine, amiodarone, cyclophosphamide).</li><li>La pneumopathie d'hypersensibilité (PHS).</li><li>Les PID associées aux <strong>connectivites</strong> (ex: PR, sclérodermie, myosite, Sjögren).</li><li>Les <strong>pneumoconioses</strong> (ex: asbestose, silicose).</li><li>Les causes <strong>malignes</strong> (ex: lymphangite carcinomateuse, adénocarcinome lépidique).</li></ul>"},{"i":"74a51a401a2c","n":210,"o":"210-1","u":"Définition","t":"Connaître la définition des pneumopathies interstitielles diffuses (PID), connaître les grandes catégories de PID","q":"Quelles sont les deux grandes catégories de pneumopathies interstitielles diffuses ?","a":"<p>Les pneumopathies interstitielles diffuses sont regroupées en deux grandes catégories selon que la cause est connue ou non :</p><ul><li>Les <strong>PID secondaires</strong> (cause connue), représentant environ <strong>35%</strong> des cas.</li><li>Les <strong>PID de cause inconnue</strong> (idiopathiques et sarcoïdose), représentant environ <strong>65%</strong> des cas.</li></ul>"},{"i":"7b91181a9cde","n":210,"o":"210-1","u":"Définition","t":"Connaître la définition des pneumopathies interstitielles diffuses (PID), connaître les grandes catégories de PID","q":"Citer des exemples de pneumopathies interstitielles diffuses de cause inconnue.","a":"<p>Les PID de cause inconnue incluent :</p><ul><li>La <strong>Fibrose Pulmonaire Idiopathique (FPI)</strong>, qui représente environ 55% des PID idiopathiques.</li><li>Les Pneumopathies Interstitielles Non Spécifiques (PINS), environ 25%.</li><li>La Pneumopathie Organisée Cryptogénique (POC).</li><li>La <strong>Sarcoïdose</strong>.</li><li>L'Histiocytose langerhansienne.</li><li>La Pneumopathie à éosinophiles.</li></ul>"}]};